static inline double hl_math_cos(double x)        { return cos(x); }
static inline double hl_math_tan(double x)        { return tan(x); }
static inline double hl_math_asin(double x)      { return asin(x); }
static inline double hl_math_acos(double x)      { return acos(x); }
static inline double hl_math_atan(double x)      { return atan(x); }
static inline double hl_math_atan2(double y, double x) { return atan2(y, x); }
static inline double hl_math_sinh(double x)      { return sinh(x); }
static inline double hl_math_cosh(double x)      { return cosh(x); }
static inline double hl_math_tanh(double x)      { return tanh(x); }
static inline double hl_math_exp(double x)       { return exp(x); }
static inline double hl_math_log(double x)       { return log(x); }
static inline double hl_math_log10(double x)     { return log10(x); }
#if defined(HL_HAVE_LOG2)
static inline double hl_math_log2(double x)      { return log2(x); }
#else
static inline double hl_math_log2(double x)      { return log(x) / log(2.0); }
#endif
static inline double hl_math_pow(double b, double e)  { return pow(b, e); }
static inline double hl_math_sqrt(double x)      { return sqrt(x); }
static inline double hl_math_cbrt(double x)      { return cbrt(x); }
static inline double hl_math_hypot(double x, double y) { return hypot(x, y); }
static inline double hl_math_fmod(double x, double y) { return fmod(x, y); }
static inline double hl_math_erf(double x)      { return erf(x); }
static inline double hl_math_erfc(double x)     { return erfc(x); }
static inline double hl_math_tgamma(double x)   { return tgamma(x); }
static inline double hl_math_lgamma(double x)   { return lgamma(x); }
static inline bool   hl_math_isnan(double x)    { return isnan(x); }
static inline bool   hl_math_isinf(double x)    { return isinf(x); }
static inline bool   hl_math_isfinite(double x)  { return isfinite(x); }
static inline bool   hl_math_signbit(double x)  { return signbit(x); }
static inline double hl_math_copysign(double x, double y) { return copysign(x, y); }

// hl_net_tcp_connect(host, port) — TCP connect to host:port.
// Returns the socket fd (>= 0) or -1 on failure. Consumes host.
static int64_t hl_net_tcp_connect(hl_str* host, int64_t port) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    struct addrinfo* res = NULL;
    char port_buf[16];
    snprintf(port_buf, sizeof(port_buf), "%lld", (long long)port);
    int rc = getaddrinfo(host->data, port_buf, &hints, &res);
    if (rc != 0 || res == NULL) {
        hl_str_release(host);
        return -1;
    }
    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (fd < 0) {
        freeaddrinfo(res);
        hl_str_release(host);
        return -1;
    }
    struct timeval tv;
    tv.tv_sec = 5; tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
        close(fd);
        freeaddrinfo(res);
        hl_str_release(host);
        return -1;
    }
    freeaddrinfo(res);
    hl_str_release(host);
    return (int64_t)fd;
}

// hl_net_tcp_listen(host, port, backlog) — bind + listen. Returns
// the listen fd or -1. SO_REUSEADDR is set so a restart doesn't
// wait for TIME_WAIT. Consumes host.
static int64_t hl_net_tcp_listen(hl_str* host, int64_t port, int64_t backlog) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        hl_str_release(host);
        return -1;
    }
    int yes = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((uint16_t)port);
    if (host->len == 0 || strcmp(host->data, "0.0.0.0") == 0) {
        addr.sin_addr.s_addr = htonl(INADDR_ANY);
    } else if (strcmp(host->data, "127.0.0.1") == 0 || strcmp(host->data, "localhost") == 0) {
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    } else if (inet_pton(AF_INET, host->data, &addr.sin_addr) != 1) {
        close(fd);
        hl_str_release(host);
        return -1;
    }
    if (bind(fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(fd);
        hl_str_release(host);
        return -1;
    }
    if (listen(fd, (int)backlog) < 0) {
        close(fd);
        hl_str_release(host);
        return -1;
    }
    hl_str_release(host);
    return (int64_t)fd;
}

// hl_net_tcp_accept(fd) — accept a connection. Returns the client
// fd or -1 on error. Blocks until a peer connects (the listen
// fd's accept timeout is inherited from the listen socket).
static int64_t hl_net_tcp_accept(int64_t fd) {
    int cfd = accept((int)fd, NULL, NULL);
    if (cfd < 0) return -1;
    struct timeval tv;
    tv.tv_sec = 30; tv.tv_usec = 0;
    setsockopt(cfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    setsockopt(cfd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
    return (int64_t)cfd;
}

// hl_net_read(fd, n) — read up to n bytes from the socket.
// Returns a fresh str (refcnt=1). Empty str at EOF or on error.
// n is clamped to a 64 KiB cap to avoid unbounded allocation.
static hl_str* hl_net_read(int64_t fd, int64_t n) {
    if (n <= 0) return hl_str_from("", 0);
    if (n > 65536) n = 65536;
    char buf[65536];
    ssize_t got = recv((int)fd, buf, (size_t)n, 0);
    if (got <= 0) return hl_str_from("", 0);
    return hl_str_from(buf, (int64_t)got);
}

// hl_net_write(fd, data) — write all bytes. Returns bytes written
// or -1 on error. Consumes data. Uses send() in a loop because
// a single send() may not write all bytes for large payloads.
static int64_t hl_net_write(int64_t fd, hl_str* data) {
    int64_t total = 0;
    while (total < data->len) {
        ssize_t w = send((int)fd, data->data + total,
                         (size_t)(data->len - total), 0);
        if (w <= 0) {
            hl_str_release(data);
            return -1;
        }
        total += w;
    }
    int64_t r = data->len;
    hl_str_release(data);
    return r;
}

// hl_net_close(fd) — close the socket. Idempotent (a double-close
// is a silent no-op, matching the interpreter).
static void hl_net_close(int64_t fd) {
    if (fd >= 0) close((int)fd);
}

// hl_net_udp_open() — create a UDP socket. Returns fd or -1.
// A 5-second recv timeout is set so recv_from doesn't hang
// forever on a dead peer (matches the interpreter).
static int64_t hl_net_udp_open() {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) return -1;
    struct timeval tv;
    tv.tv_sec = 5; tv.tv_usec = 0;
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
    return (int64_t)fd;
}

// hl_net_udp_send_to(fd, host, port, data) — send a UDP datagram.
// Returns bytes sent or -1. Consumes host and data.
static int64_t hl_net_udp_send_to(int64_t fd, hl_str* host,
                                 int64_t port, hl_str* data) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    struct addrinfo* res = NULL;
    char port_buf[16];
    snprintf(port_buf, sizeof(port_buf), "%lld", (long long)port);
    int rc = getaddrinfo(host->data, port_buf, &hints, &res);
    hl_str_release(host);
    if (rc != 0 || res == NULL) {
        hl_str_release(data);
        return -1;
    }
    ssize_t n = sendto((int)fd, data->data, (size_t)data->len, 0,
                       res->ai_addr, res->ai_addrlen);
    freeaddrinfo(res);
    int64_t r = (n >= 0) ? (int64_t)n : -1;
    hl_str_release(data);
    return r;
}

// hl_net_udp_recv_from(fd, n) — receive a UDP datagram. Returns a
// fresh str (refcnt=1). Empty str on error or timeout. The sender's
// address is discarded (callers who need it should use the raw C
// recvfrom directly via FFI — Stage 15).
static hl_str* hl_net_udp_recv_from(int64_t fd, int64_t n) {
    if (n <= 0) return hl_str_from("", 0);
    if (n > 65536) n = 65536;
    char buf[65536];
    ssize_t got = recvfrom((int)fd, buf, (size_t)n, 0, NULL, NULL);
    if (got <= 0) return hl_str_from("", 0);
    return hl_str_from(buf, (int64_t)got);
}

typedef struct { char* data; int64_t len; int64_t cap; } hl_curl_buf;
static size_t hl_curl_write_cb(char* ptr, size_t sz, size_t n, void* ud) {
    hl_curl_buf* b = (hl_curl_buf*)ud;
    size_t total = sz * n;
    if (b->len + (int64_t)total > b->cap) {
        int64_t newcap = b->cap * 2;
        if (newcap < b->len + (int64_t)total) newcap = b->len + (int64_t)total;
        char* nd = (char*)realloc(b->data, (size_t)newcap);
        if (!nd) return 0;
        b->data = nd; b->cap = newcap;
    }
    memcpy(b->data + b->len, ptr, total);
    b->len += (int64_t)total;
    return total;
}
static hl_str* hl_net_tls_get(hl_str* host, int64_t port, hl_str* path) {
    if (path->len == 0 || path->data[0] != '/') {
        char* nb = (char*)malloc((size_t)(path->len + 2));
        if (!nb) { hl_str_release(host); hl_str_release(path); hl_die("net_tls_get: oom"); }
        nb[0] = '/';
        memcpy(nb + 1, path->data, (size_t)path->len);
        nb[path->len + 1] = 0;
        hl_str* np = hl_str_from(nb, path->len + 1);
        free(nb);
        hl_str_release(path);
        path = np;
    }
    char url[4096];
    snprintf(url, sizeof(url), "https://%s:%lld%s",
             host->data, (long long)port, path->data);
    (void)url;
#ifdef HL_HAVE_LIBCURL
    CURL* c = curl_easy_init();
    if (!c) {
        hl_str_release(host); hl_str_release(path);
        hl_die("net_tls_get: curl_easy_init failed");
    }
    hl_curl_buf buf;
    buf.data = (char*)malloc(4096);
    buf.len = 0; buf.cap = 4096;
    if (!buf.data) {
        curl_easy_cleanup(c);
        hl_str_release(host); hl_str_release(path);
        hl_die("net_tls_get: oom");
    }
    curl_easy_setopt(c, CURLOPT_URL, url);
    curl_easy_setopt(c, CURLOPT_WRITEFUNCTION, hl_curl_write_cb);
    curl_easy_setopt(c, CURLOPT_WRITEDATA, &buf);
    curl_easy_setopt(c, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(c, CURLOPT_TIMEOUT, 30L);
    curl_easy_setopt(c, CURLOPT_FAILONERROR, 1L);
    CURLcode rc = curl_easy_perform(c);
    long http_code = 0;
    curl_easy_getinfo(c, CURLINFO_RESPONSE_CODE, &http_code);
    curl_easy_cleanup(c);
    hl_str_release(host); hl_str_release(path);
    if (rc != CURLE_OK) {
        free(buf.data);
        hl_die("net_tls_get: transport/TLS error");
    }
    if (http_code >= 400) {
        free(buf.data);
        hl_die("net_tls_get: HTTP error");
    }
    hl_str* out = hl_str_from(buf.data, buf.len);
    free(buf.data);
    return out;
#else
    hl_str_release(host); hl_str_release(path);
    hl_die("net_tls_get: built without libcurl (rebuild with -DHAVE_LIBCURL and link -lcurl)");
#endif
}

// ---- v0.2 additions: pop, float, chr, fmod ----
// String split helper (placed last because it depends on hl_list)
static hl_list* hl_str_split(hl_str* s, hl_str* sep) {
    if (sep->len == 0) hl_die("empty separator not allowed");
    hl_list* out = hl_list_new(hl_str_release);
    if (s->len == 0) {
        hl_list_push(out, hl_str_from("", 0));
        return out;
    }
    if (s->len < sep->len) {
        hl_list_push(out, hl_str_from(s->data, s->len));
        return out;
    }
    int64_t start = 0;
    int64_t i = 0;
    while (i <= s->len - sep->len) {
        if (memcmp(s->data + i, sep->data, (size_t)sep->len) == 0) {
            hl_list_push(out, hl_str_from(s->data + start, i - start));
            i += sep->len;
            start = i;
        } else {
            i++;
        }
    }
    hl_list_push(out, hl_str_from(s->data + start, s->len - start));
    return out;
}

// ---- v0.2 additions: pop, float, chr, fmod ----
// hl_list_pop: ownership of the removed item transfers to the caller.
static void* hl_list_pop(hl_list* l) {
    if (l->len == 0) hl_die("pop from empty list");
    l->len--;
    return l->items[l->len];
}

// Typed pops for primitive element lists: pop the box, unbox the
// value, free the box. (A plain pop + unbox would leak the box —
// the caller only wanted the primitive.)
static int64_t hl_list_pop_i64(hl_list* l) {
    void* b = hl_list_pop(l);
    int64_t v = hl_unbox_i64(b);
    free(b);
    return v;
}
static double hl_list_pop_f64(hl_list* l) {
    void* b = hl_list_pop(l);
    double v = hl_unbox_f64(b);
    free(b);
    return v;
}
static bool hl_list_pop_bool(hl_list* l) {
    void* b = hl_list_pop(l);
    bool v = hl_unbox_bool(b);
    free(b);
    return v;
}

static double hl_str_to_double(hl_str* s) {
    int64_t i = 0;
    int64_t dots = 0;
    int64_t digits = 0;
    int saw_exp = 0;
    int exp_digits = 0;
    if (s->len == 0) hl_die("cannot convert string to float");
    if (s->data[0] == '-' || s->data[0] == '+') i = 1;
    if (i >= s->len) hl_die("cannot convert string to float");
    for (; i < s->len; i++) {
        char c = s->data[i];
        if (c == '.') { if (saw_exp) hl_die("cannot convert string to float"); dots++; continue; }
        if (c == 'e' || c == 'E') {
            if (saw_exp || digits == 0) hl_die("cannot convert string to float");
            saw_exp = 1;
            if (i + 1 < s->len && (s->data[i+1] == '+' || s->data[i+1] == '-')) i++;
            exp_digits = 0;
            continue;
        }
        if (c < '0' || c > '9') hl_die("cannot convert string to float");
        if (saw_exp) exp_digits++;
        digits++;
    }
    if (dots > 1 || digits == 0) hl_die("cannot convert string to float");
    if (saw_exp && exp_digits == 0) hl_die("cannot convert string to float");
    return strtod(s->data, NULL);
}

static hl_str* hl_chr(int64_t c) {
    if (c < 0 || c > 255) hl_die("chr out of range 0..255");
    char b = (char)c;
    return hl_str_from(&b, 1);
}

static double hl_fmod(double a, double b) {
    return fmod(a, b);
}

// BUG-15 fix: range-checked float -> int64 conversion. C casts
// silently truncate out-of-range floats; we panic instead so the
// error points to the actual source of the bad value.
// Deep-scan-25 fix: the upper bound must be >= 2^63, not > 2^63.
// The old literal 9.2233720368547757e18 rounds to exactly 2^63 as
// a double, so v == 2^63 slipped past the check into (int64_t)v —
// undefined behaviour that produced a garbage value (observed as
// INT64_MAX on x86-64) while the boot interpreter panicked. There
// are no doubles strictly between INT64_MAX and 2^63, so >= 2^63
// rejects exactly the out-of-range positives.
static int64_t hl_float_to_int(double v) {
    // NaN fails BOTH comparisons, so an explicit isnan check is
    // required — otherwise the cast below is undefined behaviour.
    if (isnan(v) || v < -9.2233720368547758e18 || v >= 9.2233720368547758e18)
        hl_die("float.to_int out of int64 range");
    return (int64_t)v;
}

// hl_file_exists: consumes the path.
static bool hl_file_exists(hl_str* path) {
    hl_sandbox_check(path->data);
    struct stat st;
    bool ok = stat(path->data, &st) == 0 && S_ISREG(st.st_mode);
    hl_str_release(path);
    return ok;
}

// hl_fs_read_dir: consumes the path, returns a fresh list[str]
// of entry NAMES (not full paths). Sorted by byte-lexicographic
// order so the native binary and the interpreter (which uses
// sorted(os.listdir(...))) agree on iteration order. The list
// owns one retain per entry; each entry is a fresh hl_str*.
static hl_list* hl_fs_read_dir(hl_str* path) {
    hl_sandbox_check(path->data);
    DIR* d = opendir(path->data);
    if (!d) {
        hl_str_release(path);
        hl_die("fs_read_dir: cannot open directory");
    }
    hl_list* out = hl_list_new(hl_str_release);
    struct dirent* e;
    while ((e = readdir(d)) != NULL) {
        // Skip "." and ".." — they are always present and
        // never useful to callers (and they would create
        // infinite loops in path_walk if included).
        if (strcmp(e->d_name, ".") == 0) continue;
        if (strcmp(e->d_name, "..") == 0) continue;
        int64_t n = (int64_t)strlen(e->d_name);
        hl_list_push(out, hl_str_from(e->d_name, n));
    }
    closedir(d);
    hl_str_release(path);
    // Sort the entries by byte-lexicographic order. The list
    // owns one retain per entry; we use a simple insertion sort
    // to avoid pulling in qsort_r (which has portability
    // quirks across glibc / musl / BSD). n is typically small
    // (a single directory's entries), so O(n²) is fine here.
    for (int64_t i = 1; i < out->len; i++) {
        hl_str* v = (hl_str*)out->items[i];
        int64_t j = i;
        while (j > 0) {
            hl_str* prev = (hl_str*)out->items[j - 1];
            if (hl_str_cmp(prev, v) <= 0) break;
            out->items[j] = out->items[j - 1];
            j--;
        }
        out->items[j] = v;
    }
    return out;
}

// hl_fs_size: consumes the path, returns the file size in bytes.
// Panics on stat failure (matches the interpreter).
static int64_t hl_fs_size(hl_str* path) {
    hl_sandbox_check(path->data);
    struct stat st;
    if (stat(path->data, &st) != 0) {
        hl_str_release(path);
        hl_die("fs_size: cannot stat");
    }
    hl_str_release(path);
    return (int64_t)st.st_size;
}

// hl_fs_is_dir: consumes the path, returns true iff it is a
// directory. Returns false for non-existent paths (matches
// file_exists semantics for files).
static bool hl_fs_is_dir(hl_str* path) {
    hl_sandbox_check(path->data);
    struct stat st;
    bool ok = stat(path->data, &st) == 0 && S_ISDIR(st.st_mode);
    hl_str_release(path);
    return ok;
}

// hl_fs_set_perms: consumes the path. `mode` is the POSIX
// permission bits (e.g. 0644 = 420 decimal). Panics on chmod
// failure. The path argument is consumed (one retain) — the
// mode is a primitive int that needs no cleanup.
static void hl_fs_set_perms(hl_str* path, int64_t mode) {
    hl_sandbox_check(path->data);
    if (chmod(path->data, (mode_t)mode) != 0) {
        hl_str_release(path);
        hl_die("fs_set_perms: cannot chmod");
    }
    hl_str_release(path);
}

// clone(str) — strings are immutable, so a shallow copy is a deep copy.
static hl_str* hl_clone_str(hl_str* s) {
    return hl_str_from(s->data, s->len);
}



